package ai.decisionos.aside;
import android.content.*;import android.os.*;import android.view.*;import org.json.*;
final class GroupInlineBrowserChecks {
 static void run(GoalInstrumentation i){Bundle out=new Bundle();GoalAgentActivity h=null;try{
 h=(GoalAgentActivity)i.startActivitySync(new Intent(i.getTargetContext(),GoalAgentActivity.class).putExtra("companion_page","홈").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final GoalAgentActivity a=h;HtmlHomeChecks.waitReady(i,a.chat.companion.tossHome);NubiTossHomeUi home=a.chat.companion.tossHome;i.runOnMainSync(home::newGroupRoom);Thread.sleep(500);
 TossHomeChecks.js(i,home,"groupPending={request_id:'ui-typing-check'};render()");
 i.check("true".equals(TossHomeChecks.js(i,home,"!!document.querySelector('.group-thread .group-typing .group-dots')&&!document.querySelector('.group-composer .group-dots')")),"thinking indicator stays in chat bubble rather than composer");
 TossHomeChecks.js(i,home,"groupPending=null;render()");
 i.runOnMainSync(()->{home.showGroupPreview();a.web.loadUrl("https://chatgpt.com/?temporary-chat=true");});Thread.sleep(15000);i.runOnMainSync(home::publishBrowser);Thread.sleep(1000);
 i.check("true".equals(TossHomeChecks.js(i,home,"!!document.querySelector('.group-thread .group-browser-card')")),"browser is inside chronological thread");
 i.check("true".equals(TossHomeChecks.js(i,home,"document.getElementById('group-browser-slot').getBoundingClientRect().bottom<=document.querySelector('.group-composer').getBoundingClientRect().top")),"browser does not cover composer");
 i.check(((android.widget.FrameLayout.LayoutParams)home.groupPreview.getLayoutParams()).leftMargin<0,"default browser runs outside visible tablet viewport");
 i.check("true".equals(TossHomeChecks.js(i,home,"!groupBrowser.expanded&&!!document.querySelector('.group-browser-card img')&&document.querySelector('.group-browser-card img').naturalWidth>0")),"default card has actual snapshot rather than interactive webview");
 final java.util.concurrent.atomic.AtomicReference<String> evaluated=new java.util.concurrent.atomic.AtomicReference<>();i.runOnMainSync(()->a.web.evaluateJavascript("window.__nubiBackgroundCheck=42;String(window.__nubiBackgroundCheck)",evaluated::set));Thread.sleep(300);i.check("\"42\"".equals(evaluated.get()),"hidden browser executes JavaScript");
 i.check(((android.widget.FrameLayout.LayoutParams)home.web.getLayoutParams()).bottomMargin==0,"no fixed bottom browser dock");
 TossHomeChecks.js(i,home,"groupBrowser.expanded=false;render();browserPosition()");Thread.sleep(300);i.check(((android.widget.FrameLayout.LayoutParams)home.groupPreview.getLayoutParams()).leftMargin<0,"collapse parks browser outside viewport");
 TossHomeChecks.js(i,home,"document.querySelector('[data-action=browserToggle]').click();browserPosition()");Thread.sleep(300);i.check(((android.widget.FrameLayout.LayoutParams)home.groupPreview.getLayoutParams()).leftMargin>=0,"explicit open restores actual browser");
 for(int width:new int[]{360,600}){i.runOnMainSync(()->home.web.setLayoutParams(new android.widget.FrameLayout.LayoutParams(Ui.dp(a,width),-1)));Thread.sleep(500);TossHomeChecks.js(i,home,"browserPosition()");i.check("true".equals(TossHomeChecks.js(i,home,"document.querySelector('.group-browser-card').getBoundingClientRect().right<=innerWidth+1")),"inline browser fits "+width+"dp viewport");i.check("true".equals(TossHomeChecks.js(i,home,"document.querySelector('.group-composer button').getBoundingClientRect().right<=innerWidth+1")),"composer fits "+width+"dp viewport");}i.runOnMainSync(()->home.web.setLayoutParams(new android.widget.FrameLayout.LayoutParams(-1,-1)));Thread.sleep(400);
 final java.util.concurrent.atomic.AtomicReference<String> state=new java.util.concurrent.atomic.AtomicReference<>();i.runOnMainSync(()->a.web.evaluateJavascript("JSON.stringify({url:location.origin+location.pathname,title:document.title,composer:!!document.querySelector('#prompt-textarea,#mobile-composer-prompt'),auth:[...document.querySelectorAll('input[type=password],input[type=email]')].some(e=>!!e.getClientRects().length),body:document.body.innerText.slice(0,900)})",state::set));Thread.sleep(1000);java.nio.file.Files.write(a.getExternalFilesDir(null).toPath().resolve("gpt-connect-state.json"),String.valueOf(state.get()).getBytes(java.nio.charset.StandardCharsets.UTF_8));TossHomeChecks.js(i,home,"document.querySelector('[data-action=\"browserToggle\"]').click();browserPosition()");Thread.sleep(500);HomeUiChecks.shot(i,"group-inline-gpt.png");
 i.runOnMainSync(()->a.chat.companion.select("학교 시작하기"));Thread.sleep(1500);
 i.check(a.chat.companion.page.equals("누비톡")&&((android.widget.FrameLayout.LayoutParams)home.groupPreview.getLayoutParams()).leftMargin<0,"school connection stays in chat with browser parked");
 final android.app.AlertDialog[] login=new android.app.AlertDialog[1];TossHomeChecks.js(i,home,"document.querySelector('[data-action=schoolBackgroundLogin]').click()");Thread.sleep(500);i.runOnMainSync(()->login[0]=home.schoolLogin==null?null:home.schoolLogin.dialog);if(login[0]==null){i.check("true".equals(TossHomeChecks.js(i,home,"(groupBrowser.loginStatus||'').includes('포털 연결 완료')")),"authenticated portal reports connected without another login");i.runOnMainSync(()->login[0]=new BackgroundSchoolLogin(a,a.web).show());}else i.check(login[0].isShowing(),"actual chat connection button opens credential dialog");
 i.check((login[0].getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_SECURE)!=0,"native login blocks screen capture");
 i.check(((android.widget.FrameLayout.LayoutParams)home.groupPreview.getLayoutParams()).leftMargin<0,"credential entry keeps browser hidden");
 i.runOnMainSync(()->login[0].dismiss());
 out.putString("stream","PASS "+i.checks+" inline browser checks\n"+state.get()+"\n");
 }catch(Throwable e){out.putString("stream","FAIL "+e+"\n");}finally{if(h!=null&&!i.scenario.containsKey("keepScreen")){GoalAgentActivity a=h;i.runOnMainSync(a::finish);}}i.finish(out.getString("stream","").startsWith("PASS")?-1:0,out);}
}
